+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/contact";
+    }
+
+    @Test
+    void rendersAndHandlesSendAndNavigationDialogInChromium() {
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+
+        send.assertEnabled();
+        name.setValue("Browser User");
+        email.setValue("browser@example.com");
+        message.setValue("Sent from Chromium");
+        send.click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        send.assertDisabled();
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        grid.assertCellContent(0, 0, "Browser User");
+        grid.assertCellContent(0, 1, "Sent from Chromium");
+
+        name.setValue("Draft");
+        send.assertEnabled();
+        page.getByText("About").click();
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(dialog.getContentLocator(), "Keep editing").click();
+        name.assertValue("Draft");
+        PlaywrightAssertions.assertThat(page).hasURL(getUrl());
+
+        page.getByText("About").click();
+        ButtonElement.getByText(page, "Discard").click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        PlaywrightAssertions.assertThat(page).hasURL("http://localhost:" + port + "/about");
+    }
