+package com.example.contact;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void validatesSendsPersistsAndGuardsNavigation() {
+        navigate(ContactView.class);
+
+        assertThat(find(H1.class).withText("Contact").exists()).isTrue();
+        assertThat(find(RouterLink.class).withText("About").exists()).isTrue();
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        assertThat(send.isEnabled()).isTrue();
+        test(send).click();
+        assertThat(name.isInvalid()).isTrue();
+        assertThat(name.getErrorMessage()).isEqualTo("Name is required");
+        assertThat(email.isInvalid()).isTrue();
+        assertThat(email.getErrorMessage())
+                .isEqualTo("Give an e-mail address or a phone number");
+        assertThat(message.isInvalid()).isTrue();
+        assertThat(message.getErrorMessage()).isEqualTo("Message is required");
+        assertThat(find(Notification.class).exists()).isFalse();
+
+        test(name).setValue("Ada");
+        test(email).setValue("not-an-address");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertThat(email.isInvalid()).isTrue();
+        assertThat(email.getErrorMessage())
+                .isEqualTo("Enter a valid e-mail address");
+        assertThat(message.isInvalid()).isTrue();
+        assertThat(message.getErrorMessage())
+                .isEqualTo("Message must be at most 500 characters");
+        assertThat(message.getValue()).hasSize(501);
+
+        test(email).setValue("");
+        test(phone).setValue("123");
+        test(message).setValue("First message");
+        test(send).click();
+
+        assertThat(test(find(Notification.class).single()).getText())
+                .contains("Message sent");
+        assertThat(name.isEmpty()).isTrue();
+        assertThat(email.isEmpty()).isTrue();
+        assertThat(phone.isEmpty()).isTrue();
+        assertThat(message.isEmpty()).isTrue();
+        assertThat(send.isEnabled()).isFalse();
+
+        @SuppressWarnings("unchecked")
+        Grid<ContactMessage> grid = (Grid<ContactMessage>) find(Grid.class).single();
+        assertThat(test(grid).size()).isEqualTo(1);
+        assertThat(test(grid).getRow(0).name()).isEqualTo("Ada");
+
+        test(name).setValue("Grace");
+        test(email).setValue("grace@example.com");
+        test(message).setValue("Second message");
+        fireShortcut(com.vaadin.flow.component.Key.ENTER);
+        assertThat(test(grid).size()).isEqualTo(2);
+        assertThat(test(grid).getRow(0).name()).isEqualTo("Grace");
+        assertThat(test(grid).getRow(1).name()).isEqualTo("Ada");
+        assertThat(send.isEnabled()).isFalse();
+
+        test(name).setValue("Draft");
+        assertThat(send.isEnabled()).isTrue();
+        test(find(RouterLink.class).withText("About").single()).click();
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+
+        Dialog dialog = find(Dialog.class).single();
+        test(find(Button.class, dialog).withText("Keep editing").single()).click();
+        assertThat(name.getValue()).isEqualTo("Draft");
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+
+        test(find(RouterLink.class).withText("About").single()).click();
+        dialog = find(Dialog.class).single();
+        test(find(Button.class, dialog).withText("Discard").single()).click();
+        assertThat(getCurrentView()).isInstanceOf(AboutView.class);
+        assertThat(find(H1.class).withText("About").exists()).isTrue();
+
+        navigate(ContactView.class);
+        @SuppressWarnings("unchecked")
+        Grid<ContactMessage> returnedGrid = (Grid<ContactMessage>) find(Grid.class).single();
+        assertThat(test(returnedGrid).size()).isEqualTo(2);
+        assertThat(test(returnedGrid).getRow(0).message()).isEqualTo("Second message");
+    }
+}
